text:
Here is a self-contained HTML landing page for "Dune Line," a fictional overnight train crossing a desert to a neon city. It includes a navigation bar, a hero with a code-drawn SVG landscape, three feature highlights, a timetable, pricing tiers, a testimonial, and a footer.
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Dune Line — Overnight to Lumen City</title>
<meta name="description" content="Dune Line is a nightly sleeper train across the Erusine Desert. Board at dusk in the sand, wake to a skyline of pink and cyan.">
<style>
  /* ============ TOKENS ============ */
  :root{
    --ink:#06040d;
    --night:#0b0817;
    --panel:#100b1e;
    --line:rgba(255,255,255,.09);
    --line-2:rgba(255,255,255,.17);
    --text:#f5eef8;
    --muted:#a294b8;
    --muted-2:#7c6f92;
    --sand:#f3c795;
    --amber:#ffb26b;
    --magenta:#ff4f9a;
    --cyan:#5fe3ff;
    --serif:ui-serif,Georgia,"Times New Roman",serif;
    --sans:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
    --mono:ui-monospace,SFMono-Regular,"SF Mono",Menlo,Consolas,"Liberation Mono",monospace;
    --maxw:1160px;
    --ease:cubic-bezier(.2,.7,.3,1);
  }

  /* ============ RESET ============ */
  *,*::before,*::after{box-sizing:border-box}
  html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
  body{
    margin:0;background:var(--night);color:var(--text);
    font-family:var(--sans);font-size:16px;line-height:1.6;
    -webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;
    overflow-x:hidden;
  }
  h1,h2,h3,h4{font-family:var(--serif);font-weight:400;margin:0;letter-spacing:-.02em}
  p{margin:0}
  a{color:inherit;text-decoration:none}
  ul{margin:0;padding:0;list-style:none}
  svg{display:block}
  ::selection{background:rgba(255,79,154,.38);color:#fff}
  :focus-visible{outline:2px solid var(--sand);outline-offset:3px;border-radius:6px}
  @media (prefers-reduced-motion:reduce){
    html{scroll-behavior:auto}
    *{animation-duration:.001ms !important;transition-duration:.001ms !important}
  }

  /* ============ LAYOUT ============ */
  .container{width:min(100% - 3rem,var(--maxw));margin-inline:auto}
  .section{padding:clamp(64px,8vw,112px) 0;position:relative}
  .section + .section{border-top:1px solid var(--line)}
  [id]{scroll-margin-top:96px}

  .glow-bg{
    position:fixed;inset:0;z-index:0;pointer-events:none;
    background:
      radial-gradient(900px 620px at 8% -6%, rgba(154,107,255,.15), transparent 62%),
      radial-gradient(760px 520px at 96% 4%, rgba(255,79,154,.11), transparent 60%),
      radial-gradient(1100px 700px at 50% 108%, rgba(255,178,107,.09), transparent 64%);
  }
  .page{position:relative;z-index:1}

  /* ============ SHARED BITS ============ */
  .eyebrow{
    display:flex;align-items:center;gap:12px;
    font-family:var(--mono);font-size:.66rem;letter-spacing:.22em;
    text-transform:uppercase;color:var(--sand);margin:0 0 18px;
  }
  .eyebrow::before{content:"";width:26px;height:1px;background:linear-gradient(90deg,var(--sand),rgba(243,199,149,.1))}

  .btn{
    display:inline-flex;align-items:center;justify-content:center;gap:10px;
    padding:14px 24px;border-radius:999px;font-size:.9rem;font-weight:600;
    letter-spacing:.01em;border:1px solid transparent;cursor:pointer;
    transition:transform .25s var(--ease),box-shadow .3s var(--ease),background .3s,border-color .3s,color .3s;
    white-space:nowrap;
  }
  .btn svg{flex:none}
  .btn-primary{
    background:linear-gradient(135deg,#ff9a62 0%,#ff5c8f 52%,#ff4f9a 100%);
    color:#180710;
    box-shadow:0 12px 34px -14px rgba(255,79,154,.9), inset 0 1px 0 rgba(255,255,255,.35);
  }
  .btn-primary:hover{transform:translateY(-2px);box-shadow:0 20px 44px -16px rgba(255,79,154,1), inset 0 1px 0 rgba(255,255,255,.45)}
  .btn-ghost{
    border-color:var(--line-2);color:var(--text);
    background:rgba(255,255,255,.035);
  }
  .btn-ghost:hover{background:rgba(255,255,255,.085);border-color:rgba(255,255,255,.32);transform:translateY(-2px)}
  .btn-sm{padding:10px 18px;font-size:.82rem}

  .sec-head{
    display:grid;grid-template-columns:1.15fr .85fr;gap:clamp(24px,5vw,64px);
    align-items:end;margin-bottom:clamp(36px,4.5vw,60px);
  }
  .sec-head h2{font-size:clamp(1.95rem,3.6vw,3rem);line-height:1.05;max-width:17ch}
  .sec-lede{color:var(--muted);font-size:.98rem;max-width:46ch;padding-bottom:4px}
  @media (max-width:820px){
    .sec-head{grid-template-columns:1fr;gap:16px;align-items:start}
    .sec-lede{max-width:56ch}
  }

  .reveal{opacity:0;transform:translateY(20px);transition:opacity .8s var(--ease),transform .8s var(--ease)}
  .reveal.in{opacity:1;transform:none}

  /* ============ NAV ============ */
  .nav{
    position:fixed;top:0;left:0;right:0;z-index:60;
    border-bottom:1px solid transparent;
    transition:background .35s,border-color .35s,backdrop-filter .35s;
  }
  .nav.scrolled{
    background:rgba(8,5,16,.74);
    backdrop-filter:blur(16px) saturate(150%);
    -webkit-backdrop-filter:blur(16px) saturate(150%);
    border-bottom-color:var(--line);
  }
  .nav-inner{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:16px 0}
  .brand{display:flex;align-items:center;gap:11px;font-weight:700;font-size:.8rem;
    letter-spacing:.2em;text-transform:uppercase;color:var(--text)}
  .brand svg{width:28px;height:28px;flex:none}
  .nav-links{display:flex;gap:34px;align-items:center}
  .nav-links a{
    position:relative;font-size:.87rem;color:var(--muted);transition:color .25s;
  }
  .nav-links a::after{
    content:"";position:absolute;left:0;right:100%;bottom:-7px;height:1px;
    background:var(--sand);transition:right .35s var(--ease);
  }
  .nav-links a:hover{color:var(--text)}
  .nav-links a:hover::after{right:0}
  @media (max-width:880px){.nav-links{display:none}}

  /* ============ HERO ============ */
  .hero{
    position:relative;overflow:hidden;
    padding-top:clamp(140px,16vh,196px);
    padding-bottom:clamp(300px,40vh,430px);
    background:
      radial-gradient(95% 62% at 50% 100%, rgba(255,110,90,.15), transparent 66%),
      linear-gradient(180deg,#06040d 0%,#0a0616 28%,#130b22 54%,#1e0e2b 74%,#2d1130 100%);
  }
  .hero-sky{position:absolute;inset:0;z-index:0;pointer-events:none}
  .sky-stars{position:absolute;inset:0}
  .sky-stars i{
    position:absolute;background:#fff;border-radius:50%;
    opacity:var(--o,.6);animation:twinkle linear infinite;
  }
  @keyframes twinkle{0%,100%{opacity:var(--o,.6)}50%{opacity:calc(var(--o,.6) * .18)}}

  .hero-art{
    position:absolute;left:0;right:0;bottom:0;z-index:1;
    height:clamp(300px,34vw,460px);
    -webkit-mask-image:linear-gradient(180deg,transparent 0,#000 12%);
    mask-image:linear-gradient(180deg,transparent 0,#000 12%);
    pointer-events:none;
  }
  .hero-art svg{width:100%;height:100%}

  .hero-content{position:relative;z-index:2}
  .hero h1{
    font-size:clamp(2.9rem,6.4vw,5.3rem);line-height:.94;letter-spacing:-.035em;
    margin:0 0 26px;max-width:15ch;
  }
  .hero h1 em{
    font-style:italic;
    background:linear-gradient(120deg,#ffd6a5,#ff8fb8 55%,#c79bff);
    -webkit-background-clip:text;background-clip:text;color:transparent;
  }
  .hero .lede{
    max-width:48ch;color:#c3b6d4;font-size:clamp(.96rem,1.15vw,1.06rem);
    line-height:1.65;margin-bottom:34px;
  }
  .hero-actions{display:flex;flex-wrap:wrap;gap:14px}

  /* ============ STRIP ============ */
  .strip{
    border-top:1px solid var(--line);border-bottom:1px solid var(--line);
    background:rgba(255,255,255,.018);position:relative;z-index:2;
  }
  .strip-inner{
    display:grid;grid-template-columns:repeat(4,1fr);
    gap:24px;padding:26px 0;
  }
  .strip-item{display:flex;flex-direction:column;gap:3px}
  .strip-item + .strip-item{border-left:1px solid var(--line);padding-left:26px}
  .strip-item .k{font-family:var(--mono);font-size:.62rem;letter-spacing:.22em;text-transform:uppercase;color:var(--muted-2)}
  .strip-item .v{font-family:var(--serif);font-size:1.12rem;color:var(--text)}
  @media (max-width:760px){
    .strip-inner{grid-template-columns:1fr 1fr;gap:20px 0}
    .strip-item:nth-child(3){border-left:0;padding-left:0}
  }

  /* ============ FEATURES ============ */
  .cards{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
  .card{
    position:relative;padding:30px 28px 32px;border-radius:20px;overflow:hidden;
    background:linear-gradient(180deg,rgba(255,255,255,.055),rgba(255,255,255,.012));
    border:1px solid var(--line);
    transition:transform .4s var(--ease),border-color .4s,background .4s;
  }
  .card::after{
    content:"";position:absolute;left:0;right:0;top:0;height:1px;
    background:linear-gradient(90deg,transparent,rgba(255,178,107,.55),transparent);
    opacity:0;transition:opacity .4s;
  }
  .card:hover{transform:translateY(-4px);border-color:var(--line-2)}
  .card:hover::after{opacity:1}
  .card-icon{
    width:46px;height:46px;border-radius:13px;display:grid;place-items:center;
    background:linear-gradient(150deg,rgba(255,178,107,.2),rgba(255,79,154,.12));
    border:1px solid rgba(255,178,107,.28);color:var(--sand);
    margin-bottom:22px;
  }
  .card-icon svg{width:22px;height:22px}
  .card h3{font-size:1.3rem;margin-bottom:10px;letter-spacing:-.015em}
  .card p{color:var(--muted);font-size:.92rem;line-height:1.65}
  .card .idx{
    position:absolute;top:22px;right:24px;font-family:var(--mono);
    font-size:.66rem;letter-spacing:.18em;color:rgba(255,255,255,.22);
  }
  @media (max-width:900px){.cards{grid-template-columns:1fr}}

  /* ============ TIMETABLE ============ */
  .tt{
    border:1px solid var(--line);border-radius:20px;overflow:hidden;
    background:rgba(255,255,255,.02);
    -webkit-backdrop-filter:blur(4px);backdrop-filter:blur(4px);
  }
  .tt-head,.tt-row{
    display:grid;
    grid-template-columns:88px minmax(0,1fr) 84px 84px 92px 112px;
    gap:16px;align-items:center;
  }
  .tt-head{
    padding:16px 24px;
    font-family:var(--mono);font-size:.6rem;letter-spacing:.2em;
    text-transform:uppercase;color:var(--muted-2);
    border-bottom:1px solid var(--line);
    background:rgba(255,255,255,.022);
  }
  .tt-row{
    position:relative;padding:20px 24px;
    border-bottom:1px solid var(--line);
    transition:background .3s;
  }
  .tt-row:last-child{border-bottom:0}
  .tt-row::before{
    content:"";position:absolute;left:0;top:0;bottom:0;width:2px;
    background:linear-gradient(180deg,var(--magenta),var(--amber));
    opacity:0;transition:opacity .35s;
  }
  .tt-row:hover{background:rgba(255,255,255,.042)}
  .tt-row:hover::before{opacity:1}
  .tt-id{
    display:flex;align-items:center;gap:9px;
    font-family:var(--mono);font-size:.8rem;letter-spacing:.06em;color:var(--text);
  }
  .tt-id i{
    width:6px;height:6px;border-radius:50%;flex:none;
    background:linear-gradient(135deg,var(--amber),var(--magenta));
    box-shadow:0 0 10px rgba(255,120,160,.8);
  }
  .tt-route{
    display:flex;align-items:center;gap:10px;flex-wrap:wrap;
    font-size:.95rem;color:#d8cde6;min-width:0;
  }
  .tt-route .arw{color:var(--muted-2);flex:none}
  .tt-t{
    font-family:var(--mono);font-size:.92rem;color:var(--text);letter-spacing:.02em;
    display:flex;flex-direction:column;
  }
  .tt-d{
    font-family:var(--mono);font-size:.78rem;color:var(--muted);
    display:flex;flex-direction:column;
  }
  .pill{
    display:inline-flex;align-items:center;justify-content:center;
    padding:5px 11px;border-radius:999px;
    font-family:var(--mono);font-size:.6rem;letter-spacing:.14em;text-transform:uppercase;
    border:1px solid var(--line-2);color:var(--muted);white-space:nowrap;
  }
  .pill.hot{border-color:rgba(255,178,107,.45);color:var(--amber);background:rgba(255,178,107,.08)}
  .pill.cool{border-color:rgba(95,227,255,.4);color:var(--cyan);background:rgba(95,227,255,.07)}
  @media (max-width:900px){
    .tt-head{display:none}
    .tt-row{
      grid-template-columns:repeat(3,1fr);
      gap:14px 12px;padding:20px 18px 22px;
    }
    .tt-id{grid-column:1;grid-row:1}
    .tt-route{grid-column:1/-1;grid-row:2}
    .tt-t.dep{grid-column:1;grid-row:3}
    .tt-t.arr{grid-column:2;grid-row:3}
    .tt-d{grid-column:3;grid-row:3;align-items:flex-end}
    .tt-run{grid-column:3;grid-row:1;justify-self:end}
    .tt-t.dep::before,.tt-t.arr::before,.tt-d::before{
      content:attr(data-label);display:block;
      font-family:var(--mono);font-size:.55rem;letter-spacing:.2em;
      text-transform:uppercase;color:var(--muted-2);margin-bottom:3px;
    }
  }

  /* ============ PRICING ============ */
  .tiers{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;align-items:stretch}
  .tier{
    position:relative;display:flex;flex-direction:column;
    padding:34px 28px 30px;border-radius:22px;
    background:linear-gradient(180deg,rgba(255,255,255,.05),rgba(255,255,255,.012));
    border:1px solid var(--line);
    transition:transform .4s var(--ease),border-color .4s,box-shadow .4s;
  }
  .tier:hover{transform:translateY(-4px);border-color:var(--line-2)}
  .tier h3{font-size:1.18rem;letter-spacing:-.01em;margin-bottom:2px}
  .tier .kicker{
    font-family:var(--mono);font-size:.6rem;letter-spacing:.22em;text-transform:uppercase;
    color:var(--muted-2);margin-bottom:14px;
  }
  .price{
    font-family:var(--serif);font-size:2.9rem;line-height:1;
    display:flex;align-items:baseline;gap:5px;margin:6px 0 12px;
  }
  .price .cur{font-size:1.15rem;color:var(--sand);transform:translateY(-.55em)}
  .price .unit{
    font-family:var(--mono);font-size:.6rem;letter-spacing:.16em;text-transform:uppercase;
    color:var(--muted-2);margin-left:8px;
  }
  .tier-desc{color:var(--muted);font-size:.88rem;line-height:1.6;margin-bottom:22px}
  .tier ul{display:grid;gap:11px;margin-bottom:28px;font-size:.88rem;color:#cbbfd9}
  .tier li{display:grid;grid-template-columns:15px 1fr;gap:9px;align-items:start}
  .tier li::before{content:"✓";color:var(--sand);font-size:.76rem;line-height:1.7}
  .tier .btn{margin-top:auto;width:100%}
  .tier.featured{
    border:1px solid transparent;
    background:
      linear-gradient(180deg,#1a1029,#120b20) padding-box,
      linear-gradient(155deg,rgba(255,79,154,.85),rgba(255,178,107,.55) 45%,rgba(95,227,255,.5)) border-box;
    box-shadow:0 34px 90px -46px rgba(255,79,154,.9);
  }
  .tier.featured .kicker{color:var(--amber)}
  .tier-badge{
    position:absolute;top:-11px;left:28px;
    padding:4px 13px;border-radius:999px;
    background:linear-gradient(120deg,#ffa06a,#ff4f9a);
    color:#1b0711;font-family:var(--mono);font-size:.58rem;
    letter-spacing:.16em;text-transform:uppercase;font-weight:700;
  }
  .fares-note{
    margin-top:26px;font-family:var(--mono);font-size:.66rem;
    letter-spacing:.1em;color:var(--muted-2);text-transform:uppercase;
  }
  @media (max-width:900px){.tiers{grid-template-columns:1fr}}

  /* ============ TESTIMONIAL ============ */
  .voices{position:relative;overflow:hidden}
  .voices::before{
    content:"";position:absolute;inset:0;pointer-events:none;
    background:radial-gradient(60% 70% at 50% 0%,rgba(255,79,154,.1),transparent 70%);
  }
  .quote{position:relative;max-width:880px;margin-inline:auto;text-align:center;padding-top:20px}
  .qmark{
    position:absolute;top:-52px;left:50%;transform:translateX(-50%);
    font-family:var(--serif);font-size:9rem;line-height:1;color:rgba(243,199,149,.13);
    pointer-events:none;user-select:none;
  }
  .quote blockquote{
    position:relative;margin:0 0 34px;
    font-family:var(--serif);font-size:clamp(1.45rem,2.85vw,2.3rem);
    line-height:1.34;letter-spacing:-.02em;
  }
  .quote blockquote em{font-style:italic;color:var(--sand)}
  .stars{display:flex;justify-content:center;gap:4px;margin-bottom:22px;color:var(--amber)}
  .stars svg{width:14px;height:14px}
  .quote figcaption{
    display:inline-flex;align-items:center;gap:14px;text-align:left;
  }
  .avatar{
    width:44px;height:44px;border-radius:50%;flex:none;display:grid;place-items:center;
    font-family:var(--serif);font-size:.95rem;color:#1a0710;
    background:linear-gradient(140deg,#ffcf9a,#ff6fa5 60%,#a882ff);
    box-shadow:0 0 0 1px rgba(255,255,255,.14),0 8px 24px -10px rgba(255,79,154,.9);
  }
  .quote figcaption strong{display:block;font-size:.92rem;font-weight:600}
  .quote figcaption span{
    display:block;font-family:var(--mono);font-size:.62rem;
    letter-spacing:.14em;text-transform:uppercase;color:var(--muted-2);margin-top:3px;
  }

  /* ============ CTA ============ */
  .cta-card{
    display:flex;align-items:center;justify-content:space-between;gap:32px;flex-wrap:wrap;
    padding:clamp(30px,4.5vw,52px) clamp(26px,4.5vw,56px);
    border-radius:24px;border:1px solid var(--line);
    background:
      radial-gradient(120% 160% at 88% 0%,rgba(255,79,154,.22),transparent 58%),
      radial-gradient(90% 140% at 8% 100%,rgba(255,178,107,.16),transparent 60%),
      linear-gradient(180deg,rgba(255,255,255,.05),rgba(255,255,255,.012));
  }
  .cta-card h2{font-size:clamp(1.6rem,2.9vw,2.3rem);line-height:1.1;max-width:20ch}
  .cta-card .eyebrow{margin-bottom:14px}

  /* ============ FOOTER ============ */
  .footer{border-top:1px solid var(--line);padding:clamp(48px,6vw,76px) 0 0;background:rgba(0,0,0,.24)}
  .footer-grid{
    display:grid;grid-template-columns:1.7fr 1fr 1fr 1fr;
    gap:clamp(28px,4vw,56px);padding-bottom:clamp(36px,5vw,56px);
  }
  .footer-brand p{color:var(--muted);font-size:.88rem;max-width:34ch;margin-top:16px;line-height:1.65}
  .footer-col h4{
    font-family:var(--mono);font-size:.62rem;letter-spacing:.22em;
    text-transform:uppercase;color:var(--muted-2);margin-bottom:16px;font-weight:400;
  }
  .footer-col li{margin-bottom:10px}
  .footer-col a{font-size:.88rem;color:var(--muted);transition:color .25s}
  .footer-col a:hover{color:var(--text)}
  .footer-bottom{
    display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;
    padding:22px 0 30px;border-top:1px solid var(--line);
    font-family:var(--mono);font-size:.62rem;letter-spacing:.14em;
    text-transform:uppercase;color:var(--muted-2);
  }
  .footer-bottom .legal{display:flex;gap:22px}
  .footer-bottom a:hover{color:var(--text)}
  @media (max-width:820px){
    .footer-grid{grid-template-columns:1fr 1fr}
    .footer-brand{grid-column:1/-1}
  }
  @media (max-width:520px){
    .footer-grid{grid-template-columns:1fr}
    .footer-bottom{flex-direction:column;align-items:flex-start}
  }
</style>
</head>
<body>

<div class="glow-bg" aria-hidden="true"></div>

<div class="page">

  <!-- ================= NAV ================= -->
  <header class="nav" id="nav">
    <div class="container nav-inner">
      <a class="brand" href="#top" aria-label="Dune Line home">
        <svg viewBox="0 0 32 32" aria-hidden="true">
          <circle cx="16" cy="16" r="14.2" fill="none" stroke="rgba(243,199,149,.45)" stroke-width="1.1"/>
          <path d="M5.5 21.5c3.6-4.4 6.4-4.4 9.6 0s5.8 3.2 11.4-1" fill="none" stroke="#f3c795" stroke-width="1.6" stroke-linecap="round"/>
          <circle cx="21.6" cy="11.2" r="3.1" fill="none" stroke="#ff4f9a" stroke-width="1.4"/>
          <circle cx="21.6" cy="11.2" r="1" fill="#ff4f9a"/>
        </svg>
        <span>Dune&nbsp;Line</span>
      </a>
      <nav class="nav-links" aria-label="Primary">
        <a href="#onboard">Onboard</a>
        <a href="#timetable">Timetable</a>
        <a href="#fares">Fares</a>
