  function rnd() {
    seed = (seed * 1664525 + 1013904223) % 4294967296;
    return seed / 4294967296;
  }

  /* ---------- hero stars ---------- */
  var sky = document.querySelector(".sky-stars");
  if (sky) {
    var frag = document.createDocumentFragment();
    for (var i = 0; i < 120; i++) {
      var s = document.createElement("i");
      var size = (rnd() * 1.7 + 0.7).toFixed(1);
      s.style.left = (rnd() * 100).toFixed(2) + "%";
      s.style.top = (rnd() * 56).toFixed(2) + "%";
      s.style.width = size + "px";
      s.style.height = size + "px";
      var o = (0.15 + rnd() * 0.72).toFixed(2);
      s.style.setProperty("--o", o);
      if (rnd() > 0.5) {
        s.style.animationDuration = (2.6 + rnd() * 5.5).toFixed(2) + "s";
        s.style.animationDelay = (rnd() * 7).toFixed(2) + "s";
      } else {
        s.style.animation = "none";
      }
      frag.appendChild(s);
    }
    sky.appendChild(frag);
  }

  /* ---------- city windows ---------- */
  var winLayer = document.getElementById("win");
  var buildings = document.querySelectorAll(".bld");
  if (winLayer && buildings.length) {
    var NS = "http://www.w3.org/2000/svg";
    buildings.forEach(function (b) {
      var x = parseFloat(b.getAttribute("x"));
      var y = parseFloat(b.getAttribute("y"));
      var w = parseFloat(b.getAttribute("width"));
      var h = parseFloat(b.getAttribute("height"));

      var cw = 3.4, ch = 4.4, gx = 5.2, gy = 6.4;
      var cols = Math.floor((w - 8) / (cw + gx));
      var rows = Math.floor((h - 10) / (ch + gy));
      if (cols < 1 || rows < 1) return;

      var startX = x + (w - (cols * (cw + gx) - gx)) / 2;
      var startY = y + 6;

      for (var r = 0; r < rows; r++) {
        for (var c = 0; c < cols; c++) {
          if (rnd() < 0.44) continue;
          var rect = document.createElementNS(NS, "rect");
          rect.setAttribute("x", (startX + c * (cw + gx)).toFixed(1));
          rect.setAttribute("y", (startY + r * (ch + gy)).toFixed(1));
          rect.setAttribute("width", cw.toFixed(1));
          rect.setAttribute("height", ch.toFixed(1));
          rect.setAttribute("rx", "0.8");
          var t = rnd();
          var col = "#ffd39b";
          if (t > 0.79) col = "#5fe3ff";
          else if (t > 0.63) col = "#ff7ab8";
          rect.setAttribute("fill", col);
          rect.setAttribute("opacity", (0.22 + rnd() * 0.68).toFixed(2));
          winLayer.appendChild(rect);
        }
      }
    });
  }

  /* ---------- scroll reveal ---------- */
  var reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var targets = document.querySelectorAll(".reveal");

  if (reduce || !("IntersectionObserver" in window)) {
    targets.forEach(function (el) { el.classList.add("in"); });
  } else {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add("in");
          io.unobserve(entry.target);
        }
      });
    }, { threshold: 0.12, rootMargin: "0px 0px -6% 0px" });

    targets.forEach(function (el) {
      var parent = el.parentElement;
      var sibs = parent ? Array.prototype.filter.call(parent.children, function (c) {
        return c.classList && c.classList.contains("reveal");
      }) : [el];
      var idx = sibs.indexOf(el);
      if (idx > 0) el.style.transitionDelay = Math.min(idx * 80, 240) + "ms";
      io.observe(el);
    });
  }
})();
